// Central Game Directory Manifest for The Floor Toronto
// Auto-generated by scripts/sync-categories.js
const GAMES_DIRECTORY = (function () {
  const explicit = [
    typeof GAME_NBA_WNBA !== 'undefined' ? GAME_NBA_WNBA : null,
    typeof GAME_CAR_LOGOS !== 'undefined' ? GAME_CAR_LOGOS : null,
    typeof GAME_MARVEL_CHARACTERS !== 'undefined' ? GAME_MARVEL_CHARACTERS : null,
    typeof GAME_DOG_BREEDS !== 'undefined' ? GAME_DOG_BREEDS : null,
    typeof GAME_CANDY_BAR_TRIVIA !== 'undefined' ? GAME_CANDY_BAR_TRIVIA : null,
    typeof GAME_TAYLOR_SWIFT !== 'undefined' ? GAME_TAYLOR_SWIFT : null,
    typeof GAME_FRIENDS_TRIVIA !== 'undefined' ? GAME_FRIENDS_TRIVIA : null,
    typeof GAME_DRINKS_TRIVIA !== 'undefined' ? GAME_DRINKS_TRIVIA : null,
    typeof GAME_HIP_HOP_RNB_TRIVIA !== 'undefined' ? GAME_HIP_HOP_RNB_TRIVIA : null,
    typeof GAME_BEAUTY_PRODUCTS_TRIVIA !== 'undefined' ? GAME_BEAUTY_PRODUCTS_TRIVIA : null,
    typeof GAME_PHONE_APPS_TRIVIA !== 'undefined' ? GAME_PHONE_APPS_TRIVIA : null,
    typeof GAME_COLOURS_TRIVIA !== 'undefined' ? GAME_COLOURS_TRIVIA : null
  ].filter(Boolean);

  const registered = (typeof window !== 'undefined' && Array.isArray(window.__FLOOR_GAMES__))
    ? window.__FLOOR_GAMES__
    : [];

  const map = new Map();
  for (const g of [...explicit, ...registered]) {
    if (g && g.id && !map.has(g.id)) {
      map.set(g.id, g);
    }
  }
  return Array.from(map.values());
})();

// Helper functions for accessing and managing games
const GameRegistry = {
  getAll: function () {
    const list = [...GAMES_DIRECTORY];
    try {
      const customSaved = localStorage.getItem('the_floor_custom_games');
      if (customSaved) {
        const parsed = JSON.parse(customSaved);
        if (Array.isArray(parsed)) {
          list.push(...parsed);
        }
      }
    } catch (e) {
      console.warn('Could not load custom games', e);
    }
    return list;
  },

  getById: function (id) {
    const all = this.getAll();
    return all.find(g => g.id === id) || null;
  },

  saveCustom: function (game) {
    try {
      const customSaved = localStorage.getItem('the_floor_custom_games');
      let parsed = customSaved ? JSON.parse(customSaved) : [];
      const idx = parsed.findIndex(g => g.id === game.id);
      if (idx >= 0) {
        parsed[idx] = game;
      } else {
        parsed.unshift(game);
      }
      localStorage.setItem('the_floor_custom_games', JSON.stringify(parsed));
    } catch (e) {
      console.warn('Could not save custom game', e);
    }
  }
};
